import re
import os

# Map from type to context property name
type_map = {
    'SystemData': 'SystemData',
    'ManagedServiceIdentity': 'ManagedServiceIdentity',
    'ExtendedLocation': 'ExtendedLocation',
    'ArmPlan': 'ArmPlan',
    'ResponseError': 'ResponseError',
    'SubResource': 'SubResource',
    'OperationStatusResult': 'OperationStatusResult',
    'ManagedServiceIdentityType': 'ManagedServiceIdentityType',
    'UserAssignedIdentity': 'UserAssignedIdentity',
}

def find_balanced_parens(s, start):
    """Find the content between balanced parentheses starting at position start (which should be '(')"""
    if s[start] != '(':
        return None
    depth = 0
    for i in range(start, len(s)):
        if s[i] == '(':
            depth += 1
        elif s[i] == ')':
            depth -= 1
            if depth == 0:
                return s[start+1:i]
    return None

def fix_deserialize(content):
    for type_name, ctx_name in type_map.items():
        pattern = f'JsonSerializer.Deserialize<{type_name}>'
        while True:
            idx = content.find(pattern)
            if idx == -1:
                break
            # Find the opening paren after the pattern
            paren_start = idx + len(pattern)
            if paren_start >= len(content) or content[paren_start] != '(':
                break
            args = find_balanced_parens(content, paren_start)
            if args is None:
                break
            # Replace: JsonSerializer.Deserialize<T>(args) -> JsonSerializer.Deserialize(args, Context.Default.T)
            old = f'{pattern}({args})'
            new = f'JsonSerializer.Deserialize({args}, AzureResourceManagerJsonContext.Default.{ctx_name})'
            content = content[:idx] + new + content[idx+len(old):]
    return content

# Find all .cs files and fix
changed_files = []
for root, dirs, files in os.walk('.'):
    for f in files:
        if not f.endswith('.cs'):
            continue
        filepath = os.path.join(root, f)
        with open(filepath, 'r') as fh:
            content = fh.read()

        original = content
        content = fix_deserialize(content)

        if content != original:
            with open(filepath, 'w') as fh:
                fh.write(content)
            changed_files.append(filepath)

print(f"Fixed {len(changed_files)} files:")
for f in sorted(changed_files):
    print(f"  {f}")
